import { useState, useEffect } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [ready, setReady] = useState(false);
  useEffect(() => {
    const id = setTimeout(() => setReady(true), 100);
    // энд бичнэ үү: цэвэрлэгээ буцаа (товлолыг цуцла)
  }, []);
  return (
    <View style={styles.s}>
      <Text nativeID="msg" style={styles.c}>{ready ? "Хямдрал эхэллээ! 🎉" : "Хүлээж байна..."}</Text>
